"use strict";(self.webpackChunkmocpilot_docs=self.webpackChunkmocpilot_docs||[]).push([[8768],{1137:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/08/23/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2026/08/23/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2026-08-23-post.md","title":"Release MOCPilot 2026.5.0","description":"\ud83d\ude80 MOCPilot 2026.5.0 \u2014 Firmware-updates, SBrick-ondersteuning en bouwerverbeteringen","date":"2026-08-23T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"}],"readingTime":1.29,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2026.5.0","authors":["maxim"],"tags":["dev"]},"unlisted":false,"nextItem":{"title":"Uitgave MOCPilot 2026.4.0","permalink":"/mocpilot-app-docs/nl/blog/2026/06/06/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.5.0 \u2014 Firmware-updates, SBrick-ondersteuning en bouwerverbeteringen\\r\\n\\r\\nWe kondigen graag de release van **MOCPilot 2026.5.0** aan, beschikbaar voor **Android**, **iOS** en **macOS**.\\r\\n\\r\\nDeze update voegt firmware-update en herstelondersteuning toe voor meer LEGO Powered Up hubs, introduceert ondersteuning voor SBrick en SBrick Plus, verbetert de workflow van de blokkenbouwer en het bedieningspaneel, en bevat veel verfijningen van de gebruikersinterface, crashfixes en vertaalupdates.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Wat is nieuw in 2026.5.0?\\r\\n\\r\\n### \ud83d\udd04 Firmware-update en herstel van hubs\\r\\n\\r\\n- Firmware-updateondersteuning toegevoegd voor **Technic Hub**\\r\\n- Firmware-updateondersteuning toegevoegd voor **Technic Move Hub**\\r\\n- Firmware-updateondersteuning uitgebreid voor extra ondersteunde hubs\\r\\n- Detectie toegevoegd voor hubs die verbonden zijn in **herstelmodus**\\r\\n\\r\\n### \ud83d\udd0c Hubondersteuning en configuratie\\r\\n\\r\\n- Ondersteuning toegevoegd voor **SBrick** en **SBrick Plus**\\r\\n- Configuratiewijziging toegevoegd voor Technic Move Hub: **Porsche GT4 e-Performance**, **Batmobile\u2122\u200e Tumbler** en **Lamborghini Revuelto**\\r\\n- Hubverbindingspagina\u2019s herwerkt per verbindingstype\\r\\n- Hubmonitoringpagina herwerkt\\r\\n\\r\\n### \ud83e\uddf1 Updates voor de blokkenbouwer\\r\\n\\r\\n- Filtering op blokniveau toegevoegd: **Beginner**, **Advanced** en **Guru**\\r\\n- Blokniveaus kunnen worden geconfigureerd bij het maken, bewerken of uitvoeren van een profiel-blokprogramma\\r\\n- **batterijspanning**-blok toegevoegd voor hubs die batterijspanningsgegevens leveren\\r\\n- **vermogenspuls**-blok toegevoegd voor Technic Move Hub\\r\\n- Schaalwijzigingen met het muiswiel op het blokkenpalet opgelost\\r\\n\\r\\n### \ud83c\udfae Gamepad en bedieningspaneel\\r\\n\\r\\n- Gamepadpagina en gamepadtestpagina herwerkt\\r\\n- statusovergangen van de D-pad van de gamepad opgelost\\r\\n- Contextmenuoptie toegevoegd om het thema van bedieningselement van het bedieningspaneel direct te wijzigen\\r\\n- Profielkoppen van het bedieningspaneel, sorteermenu, kaartverlopen en afstand in het aanmaakformulier verfijnd\\r\\n\\r\\n### \ud83c\udfa8 Gebruikersinterface, profielen en stabiliteit\\r\\n\\r\\n- Gele kleurenpalet verwijderd uit vooraf gebouwde profielen, zodat ze nu lijken op de gewone profielpagina\\r\\n- Algemeen uiterlijk en kleine details van de gebruikersinterface verbeterd\\r\\n- Crashfixes en interne codeherorganisatie toegevoegd"},{"id":"/2026/06/06/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2026/06/06/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2026-06-06-post.md","title":"Uitgave MOCPilot 2026.4.0","description":"\ud83d\ude80 MOCPilot 2026.4.0 \u2014 Ongedaan maken/opnieuw, hubprofielen en bouwer-oplossingen","date":"2026-06-06T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"}],"readingTime":0.78,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Uitgave MOCPilot 2026.4.0","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2026.5.0","permalink":"/mocpilot-app-docs/nl/blog/2026/08/23/post"},"nextItem":{"title":"Release MOCPilot 2026.3.2","permalink":"/mocpilot-app-docs/nl/blog/2026/05/02/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.4.0 \u2014 Ongedaan maken/opnieuw, hubprofielen en bouwer-oplossingen\\r\\n\\r\\nWe zijn blij de uitgave van **MOCPilot 2026.4.0** aan te kondigen, beschikbaar op **Android**, **iOS** en **macOS**.\\r\\n\\r\\nDeze update voegt geschiedenis voor ongedaan maken en opnieuw uitvoeren toe voor blokprogramma\u2019s, verbetert de hubconfiguratie in de profielbouwer en lost meerdere problemen in de bouwer en apparaatbesturing op.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Wat is er nieuw in 2026.4.0?\\r\\n\\r\\n### \ud83e\uddf1 Geschiedenis voor blokprogramma\u2019s\\r\\n\\r\\n- **Geschiedenisbeheer voor ongedaan maken en opnieuw uitvoeren** toegevoegd voor blokprogramma\u2019s\\r\\n\\r\\n### \ud83d\udd0c Profielbouwer voor hubs\\r\\n\\r\\n- **Hub toevoegen** losgekoppeld van de verbindingsstroom in de profielbouwer\\r\\n- Hubs kunnen nu aan een profiel worden toegevoegd zonder verplichte directe verbinding\\r\\n\\r\\n### \ud83d\udee0 Bouwer- en apparaatoplossingen\\r\\n\\r\\n- Vertaald contextmenu-label **delete-blocks** gecorrigeerd\\r\\n- **WeDo 2.0 motorpoort-commandotoewijzing** gecorrigeerd, waardoor besturing bij gebruik van een van de twee motorpoorten is hersteld\\r\\n- Probleem met het **voorste verbindingstype** van blokken opgelost, zodat vastklikken tussen deze blokken nu correct werkt\\r\\n\\r\\n---\\r\\n\\r\\nWerk bij naar **2026.4.0** voor betere blokbewerking, flexibelere hubconfiguratie en verbeterde WeDo 2.0 motorbesturing."},{"id":"/2026/05/02/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2026/05/02/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2026-05-02-post.md","title":"Release MOCPilot 2026.3.2","description":"\ud83d\ude80 MOCPilot 2026.3.2 \u2014 Dashboardcontroller-iconen en Builder-fixes","date":"2026-05-02T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"}],"readingTime":0.75,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2026.3.2","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Uitgave MOCPilot 2026.4.0","permalink":"/mocpilot-app-docs/nl/blog/2026/06/06/post"},"nextItem":{"title":"Release MOCPilot 2026.3.1","permalink":"/mocpilot-app-docs/nl/blog/2026/04/18/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.3.2 \u2014 Dashboardcontroller-iconen en Builder-fixes\\r\\n\\r\\nWe zijn blij de release van **MOCPilot 2026.3.2** aan te kondigen, beschikbaar op **Android**, **iOS** en **macOS**.\\r\\n\\r\\nDeze update verbetert de weergave van dashboardcontrollers, lost verschillende interactieproblemen in de builder op en verfijnt het kalibratiegedrag van het stuurrek.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Wat is er nieuw in 2026.3.2?\\r\\n\\r\\n### \ud83c\udf9b Verbeteringen voor Dashboardcontrollers\\r\\n\\r\\n- **Nieuwe iconen** toegevoegd voor dashboardcontrollers\\r\\n\\r\\n### \ud83e\uddf1 Builder- en blokfixes\\r\\n\\r\\n- Een probleem opgelost waarbij de gebeurtenis **Hubkanteling gewijzigd** verkeerd kon afgaan door een vergelijking tussen gehele en decimale waarden\\r\\n- Problemen opgelost met het **vastmaken van blokken tijdens slepen**, die **C-blokken** en andere bloktypes be\xefnvloedden\\r\\n\\r\\n### \u2699\ufe0f Update voor stuurkalibratie\\r\\n\\r\\n- Het blok **Kalibreer stuurmechanisme** is herwerkt\\r\\n- Het blok zet nu de **relatieve positie terug naar `0`** wanneer de kalibratie is voltooid\\r\\n- De snelheid van het kalibratie-algoritme is bijgewerkt naar **100**\\r\\n\\r\\n---\\r\\n\\r\\nWerk bij naar **2026.3.2** voor soepeler bouwen met blokken, een verbeterde weergave van dashboardcontrollers en betrouwbaardere stuurkalibratie."},{"id":"/2026/04/18/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2026/04/18/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2026-04-18-post.md","title":"Release MOCPilot 2026.3.1","description":"\ud83d\ude80 MOCPilot 2026.3.1 \u2014 Gamepad- en Builder-update","date":"2026-04-18T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"}],"readingTime":1.38,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2026.3.1","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2026.3.2","permalink":"/mocpilot-app-docs/nl/blog/2026/05/02/post"},"nextItem":{"title":"Release MOCPilot 2026.2.3","permalink":"/mocpilot-app-docs/nl/blog/2026/02/28/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.3.1 \u2014 Gamepad- en Builder-update\\r\\n\\r\\nWe zijn blij om **MOCPilot 2026.3.1** aan te kondigen, beschikbaar voor **Android**, **iOS** en **macOS**.\\r\\n\\r\\nDeze release brengt grote verbeteringen aan de block builder (touch + desktop) en sterkere gamepad-ondersteuning.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Wat is er nieuw in 2026.3.1?\\r\\n\\r\\n### \ud83c\udfae Gamepad-verbeteringen\\r\\n\\r\\n- Gamepad-blokken worden nu **automatisch ingeschakeld** wanneer een profiel wordt geopend (ook als een gamepad al verbonden is)\\r\\n- Probleem opgelost waarbij **later toegevoegde gamepad-eventblokken** pas actief werden na het herstarten van het programma\\r\\n- Instelling voor **gamepad-waardebereik** toegevoegd voor fijnere controle\\r\\n\\r\\n### \ud83e\uddf1 Builder- en editorverbeteringen\\r\\n\\r\\n- Grote set verbeteringen aan **touch-gestures** en de algemene builder-interactie (mobiel + desktop)\\r\\n- Betrouwbaardere **undo/geschiedenis** (nu **alleen dashboard**), met een herwerkte geschiedenis die wijzigingen bijhoudt zodat je consistenter kunt terugkeren naar een vorige staat\\r\\n- Meerdere problemen in de **poorteditor** en waarde-editing op mobiel opgelost\\r\\n- Probleem opgelost op mobiel waarbij pinch-gestures het **programmagebied konden laten vastlopen**\\r\\n- Verbeterde block snapping en invoegvoorbeelden bij het bouwen van control-structuren\\r\\n- Een **halo** toegevoegd voor actieve (lopende) blokken\\r\\n\\r\\n\\r\\n### \ud83d\udd0c Hub en connectiviteit\\r\\n\\r\\n- De **hub-knopselector** in het betreffende blok is nu **altijd zichtbaar**, met herwerkte knop-eventopzet\\r\\n\\r\\n### \ud83e\udde9 Palet en help\\r\\n\\r\\n- Paletproblemen na **locale/taalwissel** opgelost (palet-actiekoppen konden inactief worden)\\r\\n- Contextmenu-optie **\u201cAbout Block\u201d** toegevoegd om documentatie voor het geselecteerde blok te openen\\r\\n\\r\\n### \ud83d\udcda Help-updates\\r\\n\\r\\n- Helppagina\u2019s uitgebreid met **directe links naar block-documentatie**\\r\\n\\r\\n### \ud83e\udd16 Android-fixes\\r\\n\\r\\n- Problemen met het **delen en importeren van profielen** op Android opgelost\\r\\n\\r\\n### \ud83d\udee0 Rendering en prestaties\\r\\n\\r\\n- **Wazige/niet-scherpe blocks** bij hoge schaal opgelost door de renderer texture-afhandeling te herwerken\\r\\n- **Texture upscaler** geoptimaliseerd voor mobiel en programma-area spacing/zoom gedrag verbeterd\\r\\n\\r\\n---\\r\\n\\r\\nUpdate naar **2026.3.1** voor een veel soepelere builder-ervaring en betere gamepad-workflows."},{"id":"/2026/02/28/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2026/02/28/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2026-02-28-post.md","title":"Release MOCPilot 2026.2.3","description":"\ud83d\ude80 MOCPilot 2026.2.3 \u2014 Dashboard- en hubfixes","date":"2026-02-28T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"}],"readingTime":0.87,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2026.2.3","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2026.3.1","permalink":"/mocpilot-app-docs/nl/blog/2026/04/18/post"},"nextItem":{"title":"Release MOCPilot 2026.2.2","permalink":"/mocpilot-app-docs/nl/blog/2026/02/18/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.2.3 \u2014 Dashboard- en hubfixes\\r\\n\\r\\nWe zijn blij om **MOCPilot 2026.2.3** aan te kondigen, beschikbaar voor **Android**, **iOS** en **macOS**.\\r\\n\\r\\nDeze update verbetert de dashboard-workflow en lost een aantal belangrijke hub- en editorproblemen op.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Wat is er nieuw in 2026.2.3?\\r\\n\\r\\n### \ud83e\uddf1 Dashboardverbeteringen\\r\\n\\r\\n- Je kunt nu **dashboard-controllers dupliceren**, met opties om **alle eigenschappen te kopi\xebren** of **alleen per type te kopi\xebren**\\r\\n- **Palette opnieuw ontworpen** voor sneller bouwen: weergegeven onder het dashboard, met een wissen-knop, blijft open na het toevoegen van componenten en houdt de sectiekeuze consistent\\r\\n\\r\\n### \ud83d\udd0c Hub-updates en fixes\\r\\n\\r\\n- **Mould King 4.0** opnieuw ge\xefmplementeerd met het **nieuwe protocol op iOS** (Android blijft het vorige protocol gebruiken)\\r\\n- Probleem opgelost waarbij het **booleaanse blok \u201chub is verbonden\u201d** niet verscheen terwijl de hub aan het adverteren was\\r\\n- Bug opgelost waarbij het **licht-blok** kon stoppen met werken door de afhandeling van motor start/stop-commando\u2019s\\r\\n\\r\\n### \ud83d\udee0 Fixes\\r\\n\\r\\n- E-mailvalidatie in de invoercomponent gecorrigeerd, waardoor ongeldige adressen zoals `mail@domain.` konden worden toegestaan\\r\\n\\r\\n---\\r\\n\\r\\nUpdate naar **2026.2.3** voor een soepelere dashboardervaring en betrouwbaardere hubs op alle platformen."},{"id":"/2026/02/18/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2026/02/18/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2026-02-18-post.md","title":"Release MOCPilot 2026.2.2","description":"\ud83d\ude80 MOCPilot 2026.2.2 \u2014 Uitgebreide hub- en besturingsupdate","date":"2026-02-18T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"}],"readingTime":1.02,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2026.2.2","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2026.2.3","permalink":"/mocpilot-app-docs/nl/blog/2026/02/28/post"},"nextItem":{"title":"Release MOCPilot 2026.1.0","permalink":"/mocpilot-app-docs/nl/blog/2026/01/10/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.2.2 \u2014 Uitgebreide hub- en besturingsupdate\\r\\n\\r\\nWe zijn verheugd de release van **MOCPilot 2026.2.2** aan te kondigen, nu beschikbaar op **Android**, **iOS** en **macOS**.\\r\\n\\r\\nDeze versie breidt de hardwarecompatibiliteit aanzienlijk uit en introduceert krachtige nieuwe programmeerblokken voor geavanceerde hub-interactie.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Wat is nieuw in 2026.2.2?\\r\\n\\r\\n### \ud83c\udd95 Nieuwe hub-ondersteuning\\r\\n\\r\\n- **Mould King 4.0 hubs** worden nu volledig ondersteund  \\r\\n- **Mould King 6.0 hubs** worden nu volledig ondersteund  \\r\\n- **LEGO WeDo 2.0 hub** wordt nu volledig ondersteund  \\r\\n\\r\\n---\\r\\n\\r\\n### \ud83d\udd0c Sensorondersteuning\\r\\n\\r\\n- WeDo 2.0 kantelsensor  \\r\\n- WeDo 2.0 bewegingssensor\\r\\n\\r\\n---\\r\\n\\r\\n### \ud83e\uddf1 Nieuwe programmeerblokken\\r\\n\\r\\nDeze release introduceert nieuwe gebeurtenis- en besturingsblokken die de realtime interactiemogelijkheden met hubs uitbreiden.\\r\\n\\r\\n#### \ud83d\udd04 Hub-sensorgebeurtenisblokken\\r\\n- **Hub-accelerometergegevens gewijzigd**  \\r\\n- **Hub-kanteling gewijzigd**  \\r\\n- **Hub-ori\xebntatie gewijzigd**  \\r\\n- **Batterijniveau van alle hubs gewijzigd**\\r\\n\\r\\nMet deze blokken kan je programma direct reageren op beweging, rotatie en stroomveranderingen.\\r\\n\\r\\n#### \ud83d\udd0c Hub-verbindingsbesturingsblokken\\r\\n- **Hub verbinden**\\r\\n- **Hub loskoppelen**\\r\\n\\r\\nJe kunt nu hubverbindingen rechtstreeks beheren tijdens de uitvoering van het programma.  \\r\\nHierdoor kun je een hub opnieuw verbinden zonder het programma opnieuw te starten als de verbinding wordt verbroken, wat projecten robuuster en flexibeler maakt.\\r\\n\\r\\n---\\r\\n\\r\\n### \u2699\ufe0f Verbeteringen\\r\\n\\r\\n- Verbeterde algehele systeemstabiliteit  \\r\\n- Prestatie-optimalisaties voor soepelere hub-interactie  \\r\\n- Kleine verbeteringen in UI en lay-out  \\r\\n\\r\\n---\\r\\n\\r\\nUpdate MOCPilot naar de nieuwste versie en begin met bouwen met uitgebreide hubcompatibiliteit en krachtige realtime besturingsmogelijkheden op al je apparaten."},{"id":"/2026/01/10/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2026/01/10/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2026-01-10-post.md","title":"Release MOCPilot 2026.1.0","description":"\ud83d\ude80 MOCPilot 2026.1.0 \u2014 Functie- & stabiliteitsupdate","date":"2026-01-10T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"}],"readingTime":1.1,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2026.1.0","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2026.2.2","permalink":"/mocpilot-app-docs/nl/blog/2026/02/18/post"},"nextItem":{"title":"Release MOCPilot 2025.2.0 - 2025.2.4","permalink":"/mocpilot-app-docs/nl/blog/2025/12/28/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.1.0 \u2014 Functie- & stabiliteitsupdate\\r\\n\\r\\nWe zijn blij de release van **MOCPilot 2026.1.0** aan te kondigen, nu beschikbaar op **Android**, **iOS** en **macOS**.\\r\\n\\r\\nDeze release introduceert de **gastmodus**, verbetert de bruikbaarheid op mobiele apparaten en levert belangrijke stabiliteits- en prestatiefixes op alle ondersteunde platforms.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Wat is er nieuw in 2026.1.0?\\r\\n\\r\\n### \ud83c\udd95 Nieuw\\r\\n- **Gastmodus** \u2014 gebruik de app zonder account, met de optie om later een account aan te maken\\r\\n- Taalkeuze toegevoegd aan het authenticatiescherm\\r\\n- De app blokkeert nu het gebruik van hubs met niet-ondersteunde firmware en toont een duidelijke waarschuwing\\r\\n\\r\\n### \u2699\ufe0f Verbeteringen\\r\\n- Verbeterd blokken slepen op mobiel (betere touch-afhandeling, minder per ongeluk aanraken)\\r\\n- Het blokkenpalet wordt nu automatisch verborgen tijdens het slepen op mobiel\\r\\n- Waarschuwingsdialogen passen nu een blur-effect toe op de achtergrond\\r\\n- Verbeterde tekstinvoer op alle platforms\\r\\n- Soepelere hub-bediening met lagere latency\\r\\n\\r\\n### \ud83d\udee0 Oplossingen\\r\\n- Meerdere drag & drop-problemen opgelost, inclusief vastzittende blokken en verloren muis-/touch-invoer\\r\\n- Crashes opgelost bij het stoppen van programma\u2019s die aangepaste (\u201cMy\u201d) blokken gebruiken\\r\\n- Probleem opgelost waarbij de stuurheugelkalibratie niet terugkeerde naar het midden\\r\\n- Hub-bedieningslag en vertraagde motorrespons opgelost\\r\\n- Problemen opgelost met editorpoorten, sliders en snelheidswaarde-blokken\\r\\n- Probleem met het hoofdvenster en diverse UI-layoutproblemen opgelost\\r\\n- Vertalingen bijgewerkt en kleine visuele inconsistenties opgelost\\r\\n\\r\\n---\\r\\n\\r\\nWerk MOCPilot bij naar de nieuwste versie en geniet van een soepelere, stabielere en toegankelijkere ervaring op al je apparaten."},{"id":"/2025/12/28/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2025/12/28/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2025-12-28-post.md","title":"Release MOCPilot 2025.2.0 - 2025.2.4","description":"\ud83d\ude80 MOCPilot 2025.2.0 - 2025.2.4 \u2014 Stabiliteits- en ervaringsupdate","date":"2025-12-28T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"}],"readingTime":0.63,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2025.2.0 - 2025.2.4","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2026.1.0","permalink":"/mocpilot-app-docs/nl/blog/2026/01/10/post"},"nextItem":{"title":"Release MOCPilot 2025.2.0","permalink":"/mocpilot-app-docs/nl/blog/2025/11/15/post"}},"content":"## \ud83d\ude80 MOCPilot 2025.2.0 - 2025.2.4 \u2014 Stabiliteits- en ervaringsupdate\\r\\n\\r\\nWe zijn blij de release van **MOCPilot 2025.2.0 - 2025.2.4** aan te kondigen, nu beschikbaar op **Android**, **iOS** en **macOS**.\\r\\n\\r\\nDeze release richt zich op **soepeler gedrag**, **betere betrouwbaarheid** en **UI-verbeteringen** op alle platforms.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Wat is verbeterd in 2025.2.0 - 2025.2.4?\\r\\n\\r\\n- Soepeler en stabieler gedrag dankzij verbeterde timinglogica\\r\\n- Verbeterde profiel\xadsynchronisatie en updatebetrouwbaarheid\\r\\n- Verbeterde lay-out van de profiellijst met duidelijkere informatie\\r\\n- Verbeterde visuals en interactie van de aura-schuifregelaar\\r\\n- Oplossing voor pitch/roll-omkeringsproblemen in besturing\\r\\n- Verbeterde UI-lay-outs op telefoons en tablets\\r\\n- Oplossingen voor kleur-, schakelaar- en visuele consistentieproblemen\\r\\n- Verbeterde vertalingen en tekstconsistentie\\r\\n- Algemene bugfixes, prestatie- en stabiliteitsverbeteringen\\r\\n\\r\\n---\\r\\n\\r\\nWerk MOCPilot bij naar de nieuwste versie en geniet van een stabielere en responsievere ervaring op al je apparaten."},{"id":"/2025/11/15/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2025/11/15/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2025-11-15-post.md","title":"Release MOCPilot 2025.2.0","description":"\ud83d\ude80 MOCPilot 2025.2.0 \u2014 Offici\xeble multiplatform release!","date":"2025-11-15T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"}],"readingTime":0.56,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2025.2.0","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2025.2.0 - 2025.2.4","permalink":"/mocpilot-app-docs/nl/blog/2025/12/28/post"},"nextItem":{"title":"Release MOCPilot 2025.1.9","permalink":"/mocpilot-app-docs/nl/blog/2025/06/3/post"}},"content":"## \ud83d\ude80 MOCPilot 2025.2.0 \u2014 Offici\xeble multiplatform release!\\r\\n\\r\\nWe zijn verheugd om de offici\xeble release van **MOCPilot 2025.2.0** aan te kondigen, nu beschikbaar op **Android**, **iOS** en **macOS**!\\r\\n\\r\\nDe app die vroeger **Controlz** heette, is nu omgedoopt tot **MOCPilot**, een naam die beter aansluit bij de visie op de lange termijn: \xe9\xe9n centrale piloot-omgeving voor het besturen en programmeren van je LEGO\xae-creaties.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Wat is er nieuw in 2025.2.0?\\r\\n\\r\\n- Ge\xfcnificeerde release voor Android, iOS en macOS  \\r\\n- Verbeterde stabiliteit, prestaties en UI-respons  \\r\\n- Nieuwe merkidentiteit onder de naam *MOCPilot*  \\r\\n- Voortdurende ondersteuning voor LEGO\xae Control+, BuWizz 2/3 en aangepaste Bluetooth-modules  \\r\\n\\r\\n---\\r\\n\\r\\nDownload MOCPilot vandaag nog en ervaar de volgende generatie controle over je LEGO\xae-modellen!"},{"id":"/2025/06/3/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2025/06/3/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2025-06-3-post.md","title":"Release MOCPilot 2025.1.9","description":"\ud83d\ude80 MOCPilot 2025.1.9 is nu beschikbaar in de Mac App Store!","date":"2025-06-03T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/nl/blog/tags/test","description":"Testing news"}],"readingTime":0.33,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2025.1.9","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2025.2.0","permalink":"/mocpilot-app-docs/nl/blog/2025/11/15/post"},"nextItem":{"title":"Release MOCPilot 2025.1.5","permalink":"/mocpilot-app-docs/nl/blog/2025/05/17/post"}},"content":"import { MacAppStoreBadge } from \'@site/src/pages/\';\\r\\n\\r\\n## \ud83d\ude80 MOCPilot 2025.1.9 is nu beschikbaar in de Mac App Store!\\r\\n\\r\\nWe zijn verheugd de release van MOCPilot 2025.1.9 als een native macOS-app aan te kondigen!\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\nJe kunt nu genieten van volledige desktopprestaties en naadloze integratie met macOS.  \\r\\nDownload het vandaag nog vanuit de Mac App Store en neem de controle over je LEGO\xae creaties als nooit tevoren!\\r\\n\\r\\n<MacAppStoreBadge/>"},{"id":"/2025/05/17/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2025/05/17/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2025-05-17-post.md","title":"Release MOCPilot 2025.1.5","description":"Beschrijving","date":"2025-05-17T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/nl/blog/tags/test","description":"Testing news"}],"readingTime":0.53,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2025.1.5","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2025.1.9","permalink":"/mocpilot-app-docs/nl/blog/2025/06/3/post"},"nextItem":{"title":"Release MOCPilot 2025.1.4","permalink":"/mocpilot-app-docs/nl/blog/2025/05/10/post"}},"content":"### Beschrijving\\r\\n\\r\\nDeze update verbetert de blokbewerkingservaring, verhoogt de prestaties en zorgt voor correcte werking op nieuwere Android-versies.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\n### Wijzigingen\\r\\n\\r\\n- **Opgelost: een bug bij het scannen van hubs op Android 12+** door nu om precieze locatie-toestemming te vragen.\\r\\n- **Toegevoegd: een optie om het blokkenpalet te tonen/verbergen** door te klikken op de momenteel geselecteerde blokverzameling.\\r\\n- **Toegevoegd: een formaatgreep** aan het blokkenpalet om **handmatig te kunnen schalen**.\\r\\n- **Opgelost: hoge CPU-belasting** wanneer een profiel werd geladen, maar het programma niet draaide.\\r\\n- **Verbeterd: de editor van het blok \\"Stringlijst\\"** zodat inhoud niet meer wordt afgekapt. Items worden nu gesplitst in kolommen voor betere leesbaarheid bij grote lijsten."},{"id":"/2025/05/10/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2025/05/10/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2025-05-10-post.md","title":"Release MOCPilot 2025.1.4","description":"Beschrijving","date":"2025-05-10T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/nl/blog/tags/test","description":"Testing news"}],"readingTime":0.81,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2025.1.4","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2025.1.5","permalink":"/mocpilot-app-docs/nl/blog/2025/05/17/post"},"nextItem":{"title":"Release MOCPilot 2025.1.2 - 2025.1.3","permalink":"/mocpilot-app-docs/nl/blog/2025/04/19/post"}},"content":"### Beschrijving\\r\\n\\r\\nDeze update verbetert de ondersteuning voor tablets, voegt nuttige testpagina\'s toe en lost diverse compatibiliteits- en prestatieproblemen op.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\n### Wijzigingen\\r\\n\\r\\n- **Tabletindeling toegevoegd** voor betere benutting van grotere schermen.\\r\\n- **Opgelost: een bug waarbij het blok \\"hubknop ingedrukt\\"** verscheen voor hubs die deze actie niet ondersteunen. Ook zijn **verkeerde kleuren sensorblokken** voor niet-ondersteunde hubs (zoals BuWizz) opgelost.\\r\\n- **Opgelost: een bug waarbij het blok \\"motor starten\\"** geen effect had op motoren zonder encoders vanwege ontbrekende alternatieve commando\'s.\\r\\n- **Toegevoegd: een pagina voor het testen van gamepadknoppen.**\\r\\n- **Toegevoegd: een testpagina voor hubs** met een dashboard dat informatie, verbonden poortapparaten en poortschudstatus toont.\\r\\n- **Opgelost: onjuiste interpretatie van versnellingsmetergegevens** voor BuWizz 2 en 3, die leidde tot foutieve ori\xebntatiemeldingen.\\r\\n- **Opgelost: RAM-geheugenlekken** die leidden tot het afsluiten van de app op sommige apparaten vanwege hoog geheugengebruik.\\r\\n- **Opgelost: bugs bij het laden van profielen** die eerder tot crashes leidden in bepaalde scenario\'s.\\r\\n- **Opgelost: een Android-bug** waarbij het loslaten van gamepadsticks de aswaarden niet terugzette naar nul."},{"id":"/2025/04/19/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2025/04/19/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2025-04-19-post.md","title":"Release MOCPilot 2025.1.2 - 2025.1.3","description":"Beschrijving","date":"2025-04-19T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/nl/blog/tags/test","description":"Testing news"}],"readingTime":0.4,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2025.1.2 - 2025.1.3","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2025.1.4","permalink":"/mocpilot-app-docs/nl/blog/2025/05/10/post"},"nextItem":{"title":"Release MOCPilot 2025.1.1","permalink":"/mocpilot-app-docs/nl/blog/2025/04/14/post"}},"content":"### Beschrijving\\r\\n\\r\\nDeze update introduceert nieuwe aanpassingsopties voor joysticks, UI-verbeteringen en belangrijke stabiliteitsoplossingen.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\n### Wijzigingen\\r\\n\\r\\n- **Opgelost: een bug in de blokkenpalet-collectie-selector**: het selecteren van een collectie, scrollen naar een andere en terugkeren had geen effect.\\r\\n- **Opgelost: een crash bij het laden van zware profielen** met een groot aantal blokken.\\r\\n- **Toegevoegd: \u201cAssentype\u201d-eigenschap** in joystickinstellingen ter ondersteuning van **enkelassige modus** (X, Y, XY).\\r\\n- **Toegevoegd: kleuraccenten** voor stuurwielcontrollers (\u201cGMZ\u201d, \u201cNo Mercy\u201d).\\r\\n- **Toegevoegd: \u201cis ingedrukt\u201d-blokken** voor stuurwielen en pedalen."},{"id":"/2025/04/14/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2025/04/14/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2025-04-14-post.md","title":"Release MOCPilot 2025.1.1","description":"Beschrijving","date":"2025-04-14T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/nl/blog/tags/test","description":"Testing news"}],"readingTime":0.49,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2025.1.1","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2025.1.2 - 2025.1.3","permalink":"/mocpilot-app-docs/nl/blog/2025/04/19/post"},"nextItem":{"title":"MOCPilot 2025.1.0","permalink":"/mocpilot-app-docs/nl/blog/2025/04/04/post"}},"content":"### Beschrijving\\r\\n\\r\\nDeze update bevat een aantal belangrijke bugfixes die de prestaties verbeteren, het batterijverbruik verminderen en het gedrag van blokken in de programmeeromgeving verbeteren.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\n### Wijzigingen\\r\\n\\r\\n- **Opgelost: een bug die leidde tot hoog CPU-gebruik, batterijverbruik en lage prestaties.**\\r\\n- **Opgelost: een bug waarbij gamepadblokken** (bijv. \u201cis knop ingedrukt\u201d, \u201cis D-PAD-knop ingedrukt\u201d) **niet konden worden gekoppeld aan andere blokken.**\\r\\n- **Opgelost: een probleem in het \\"step switch event\\" blok** waarbij aanrakingen en stapregistratie onjuist werden verwerkt.\\r\\n- **Opgelost: een bug in het \\"item van\\" blok voor lijsten** waarbij niet meer dan \xe9\xe9n blok als argumentindex kon worden gekoppeld."},{"id":"/2025/04/04/post","metadata":{"permalink":"/mocpilot-app-docs/nl/blog/2025/04/04/post","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2025-04-04-post.md","title":"MOCPilot 2025.1.0","description":"\ud83d\ude80 MOCPilot 2025.1.0 Gesloten B\xe8ta is Begonnen!","date":"2025-04-04T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/nl/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/nl/blog/tags/test","description":"Testing news"}],"readingTime":0.32,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/nl/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"MOCPilot 2025.1.0","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2025.1.1","permalink":"/mocpilot-app-docs/nl/blog/2025/04/14/post"}},"content":"## \ud83d\ude80 MOCPilot 2025.1.0 Gesloten B\xe8ta is Begonnen!\\r\\n\\r\\nWe zijn verheugd aan te kondigen dat de gesloten b\xe8ta voor MOCPilot 2025 nu live is! Geselecteerde gebruikers kunnen nu nieuwe functies verkennen, feedback geven en helpen de toekomst van MOCPilot vorm te geven.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\nAls je een uitnodiging hebt ontvangen, controleer dan je e-mail voor toegangsgegevens.  \\r\\nBedankt dat je deel uitmaakt van deze belangrijke fase!"}]}}')}}]);